// ============ Message Input Types ============

/**
 * User message input - id generated by frontend
 */
export interface UserMessage {
	content: ChatContent[];
}

/**
 * AI message input - id from backend
 */
export interface AIMessage {
	id: string;
	content: ChatContent[];
}

// ============ Stored Message Type ============

/**
 * Chat message with multimodal content support
 */
export interface ChatMessage {
	id: string;
	role: 'user' | 'assistant';
	/** Array of content items - supports text, images, or mixed */
	content: ChatContent[];
}

/**
 * Chat request - matches backend ChatRequest schema
 */
export interface ChatRequest {
	thread_id: string;
	project_id: string | null;
	content: any;
	source_ids?: string[];
}

/**
 * Chat response - matches backend ChatResponse schema
 */
export interface ChatResponse {
	id: string;
	role: 'user' | 'assistant';
	content: any;
	created_at: string;
}